/* Loot keys/sigils: random chest items and drops may also be keys or sigils
 * (ChaoticBrave's behavior). Vanilla key/sigil sources are never touched. */
#pragma once
#include "rng.h"
#include "vs.h"

/* One room in story order (generated by tools/gen_keyrooms.py). */
typedef struct {
    u16 roomKey; /* zone << 8 | index in the zone's MPD list */
    u8 area; /* story-ordered area, Reference_Files.cpp map_list index */
    u8 preMinotaur; /* the Chamomile Sigil may not appear here */
    u8 chestSlots; /* eligible chest misc slots (bit per slot) */
    u8 drops; /* eligible enemy drops */
} keyRoom_t;

extern const keyRoom_t keyRooms[];
extern const int keyRoomCount;

enum { KEY_PASS_CHESTS, KEY_PASS_DROPS };

/* Story-ordered area (0-20) of a room, or -1 if it is not in the table. */
int keys_roomArea(u32 roomKey);

#define KEY_MAX_DRAWS 8

/* Items for a room's eligible draws: out[slot] for chest misc slots, out[n]
 * for the n-th eligible drop. Returns 0 if the room is not in the table. */
int keys_roomItems(u32 roomKey, int pass, u16 out[KEY_MAX_DRAWS]);
